select o.id,d.id,'commuter',(select id from public.aircraft_types where code='B737'),case when d.local_code='STN7' or o.local_code='STN7' then 35 else 25 end,case when d.local_code='STN7' then 20000 else 14000 end,case when o.local_code='STN7' then 19000 else 15000 end,10,true,'Historically inspired; editable fictional operation' from public.airports o join public.airports d on (o.local_code,d.local_code) in (('STN9','STN3'),('STN3','STN9'),('STN9','STN7'),('STN7','STN9'),('STN3','STN1'),('STN1','STN3'),('STN9','STN1'),('STN1','STN9'));
